#!/usr/bin/env python3
"""Regenerates web_fonts.inc: DEFLATE, gzip and WOFF fixtures made by the reference zlib."""
import gzip, io, os, struct, zlib
def arr(name, b):
    lines = []
    for i in range(0, len(b), 16):
        lines.append("    " + ", ".join("0x%02x" % x for x in b[i:i+16]) + ",")
    return "const uint8_t %s[] = {\n%s\n};\n" % (name, "\n".join(lines))
text = (b"Zepra decodes its own DEFLATE streams. " * 3 + bytes(range(256)) + b"abcabcabcabcabcabc" * 9)
out = []
out.append("// Text every stream below decodes to\nconst char kPlainPrefix[] = \"Zepra decodes its own DEFLATE streams. \";\n")
out.append(arr("kZlibDynamic", zlib.compress(text, 9)))
c = zlib.compressobj(9, zlib.DEFLATED, 15, 9, zlib.Z_FIXED); out.append(arr("kZlibFixed", c.compress(text) + c.flush()))
c = zlib.compressobj(0, zlib.DEFLATED, 15); out.append(arr("kZlibStored", c.compress(text) + c.flush()))
buf = io.BytesIO()
with gzip.GzipFile(filename="hello.txt", mode="wb", fileobj=buf, mtime=0) as g: g.write(text)
out.append(arr("kGzipNamed", buf.getvalue()))
# Synthetic sfnt -> WOFF (one table compressed, one stored)
tabs = [(b"zzzz", b"0123456789abcdef" * 40), (b"aaaa", bytes([7, 9, 11]))]  # unsorted on purpose
def woff(tabs):
    n = len(tabs); hdr = 44 + 20 * n; data = b""; dirs = []
    for tag, t in tabs:
        comp = zlib.compress(t)
        body = comp if len(comp) < len(t) else t
        off = hdr + len(data)
        dirs.append(struct.pack(">4sIIII", tag, off, len(body), len(t), 0x12345678))
        data += body + b"\0" * ((-len(body)) % 4)
    total = 12 + 16 * n + sum((len(t) + 3) & ~3 for _, t in tabs)
    h = struct.pack(">4sIIHHIHHIIIII", b"wOFF", 0x00010000, hdr + len(data), n, 0, total, 1, 0, 0, 0, 0, 0, 0)
    return h + b"".join(dirs) + data
out.append(arr("kWoffSynthetic", woff(tabs)))
open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "web_fonts.inc"), "w").write(
  "// Generated by gen_web_fonts.py with Python's zlib and gzip modules,\n"
  "// the reference encoder Zepra's own decoder is tested against. Do not edit.\n" + "\n".join(out))
